import math

def get_sigma(m):
    """Calculates the sum of divisors sigma(m)."""
    sum_div = 0
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            sum_div += i
            if i * i != m:
                sum_div += m // i
    return sum_div

def is_square(n):
    """Checks if n is a perfect square."""
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def get_divisors(m):
    """Returns a list of divisors of m."""
    divs = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.append(i)
            if i * i != m:
                divs.append(m // i)
    divs.sort()
    return divs

def solve_m(m):
    sigma_m = get_sigma(m)
    if not is_square(sigma_m):
        return None # Condition 1 failed

    divisors = get_divisors(m)
    n = len(divisors)

    # Check for permutation existence using backtracking/DFS

    # 1. Find possible starting squares a1
    initial_squares = [d for d in divisors if is_square(d)]

    if not initial_squares:
        return None # No starting square found

    for start_a1 in initial_squares:

        # Initial state: current sum S1 = start_a1, remaining divisors = D \ {a1}
        remaining_divisors = divisors[:]
        remaining_divisors.remove(start_a1)

        current_sum = start_a1

        # Check if S1 is a square (it is, by selection)
        if not is_square(current_sum):
             # This should not happen if start_a1 is a square
             continue 

        # DFS function: current_sum, remaining_divs, path_so_far
        def dfs(current_sum, remaining_divs, path):
            if not remaining_divs:
                # Reached the end. Check final sum (should be sigma_m, which is a square)
                return current_sum == sigma_m

            for i in range(len(remaining_divs)):
                a_i = remaining_divs[i]
                next_sum = current_sum + a_i

                if is_square(next_sum):
                    # Try this step
                    next_remaining = remaining_divs[:i] + remaining_divs[i+1:]
                    path.append(a_i)

                    if dfs(next_sum, next_remaining, path):
                        return True

                    # Backtrack
                    path.pop()
            return False

        # Start DFS from the chosen initial square
        if dfs(start_a1, remaining_divisors, [start_a1]):
            return m # Solution found for this m

    return None # No starting square led to a full solution

solutions = []
for m in range(3, 51):
    solution = solve_m(m)
    if solution:
        solutions.append(solution)

print("Solutions found (m):", solutions)

