from collections import defaultdict

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def sigma(n):
    # Calculates the sum of divisors sigma(n)
    def prime_factorization(num):
        factors = defaultdict(int)
        d = 2
        temp = num
        while d * d <= temp:
            while temp % d == 0:
                factors[d] += 1
                temp //= d
            d += 1
        if temp > 1:
            factors[temp] += 1
        return factors

    factors = prime_factorization(n)
    sum_div = 1
    for p, a in factors.items():
        sum_div *= (p**(a+1) - 1) // (p - 1)
    return sum_div

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_backtracking(divisors):
    n = len(divisors)
    divisors_set = set(divisors)

    # Sort divisors for consistency, although the search is permutation-based
    # We check all possible starting points

    def backtrack(current_sum, remaining_divisors, path):
        # Base case: All divisors used
        if not remaining_divisors:
            # Since we checked the final sum (which must be sigma(m)), 
            # and all intermediate sums were checked in recursive calls, 
            # we found a solution.
            return True

        # Iterate through remaining divisors
        for i, d in enumerate(remaining_divisors):
            if d not in remaining_divisors:
                continue

            next_sum = current_sum + d

            # Check if the next partial sum is a perfect square
            if is_perfect_square(next_sum):
                # Try this divisor
                new_remaining = remaining_divisors - {d}
                new_path = path + [d]

                if backtrack(next_sum, new_remaining, new_path):
                    return True

        return False

    # The initial sum must be 0, and the first chosen divisor a1 must be a perfect square.
    # Iterate through all divisors d as potential a1
    for d1 in divisors:
        if is_perfect_square(d1):
            initial_sum = d1
            if is_perfect_square(initial_sum): # Always true if d1 is square
                remaining = divisors_set - {d1}
                if backtrack(initial_sum, remaining, [d1]):
                    return True # A valid permutation exists

    return False

